INSERT INTO feature VALUES('thunks-and-force','calculus','Thunks and forcing','call-by-push-value','implemented','notable',NULL,'A computation is suspended as a value by `thunk` and resumed by `force`, the type `+U` naming the suspension. The bare name of a `def` of no input runs it in each position, a type''s too, and `thunk { f }` passes it as a value.','core-term core-nbe surface-lowering','corpus/model/identity/cong-thunk.gandr corpus/ledger/features/thunks-and-force.gandr','corpus/ledger/features/thunks-and-force.gandr',NULL);
